/* -------------------------------------------------------------------------
 * Fix cho OLED 1.3 inch dùng controller SH1106.
 *
 * Lý do sửa:
 * - SH1106 không dùng tốt bộ lệnh SSD1306_COLUMNADDR(0x21)/PAGEADDR(0x22)
 *   như thư viện cũ.
 * - SH1106 có RAM 132 cột, màn 128 cột thường bắt đầu lệch +2 cột.
 * - Gửi 1024 byte một phát khi clear dễ gây nháy/nhiễu trên một số module I2C.
 *
 * Nếu chữ bị lệch trái/phải, thử đổi SH1106_COL_OFFSET từ 2 sang 0 hoặc 4.
 * ------------------------------------------------------------------------- */
#ifndef SH1106_COL_OFFSET
#define SH1106_COL_OFFSET    2
#endif

#define OLED_I2C_TIMEOUT     100
#define OLED_PAGE_COUNT      (SSD1306_LCDHEIGHT / 8)

static void OLED_Write_Command_1byte(uint8_t byte1)
{
	uint8_t datos[2] = {CMD, byte1};
	HAL_I2C_Master_Transmit(&hi2c1, SSD1306_I2C_ADDRESS, datos, 2, OLED_I2C_TIMEOUT);
}

static void OLED_Set_Pos_SH1106(uint8_t page, uint8_t col)
{
	uint8_t real_col;

	if(page >= OLED_PAGE_COUNT) return;
	if(col >= SSD1306_LCDWIDTH) return;

	real_col = col + SH1106_COL_OFFSET;

	/* SH1106 page addressing */
	OLED_Write_Command_1byte(0xB0 | (page & 0x0F));
	OLED_Write_Command_1byte(0x00 | (real_col & 0x0F));
	OLED_Write_Command_1byte(0x10 | ((real_col >> 4) & 0x0F));
}

static void OLED_Write_Data_Buffer(const uint8_t *buffer, uint16_t length)
{
	uint8_t datos[129];
	uint16_t i;

	/* Gửi tối đa 128 byte data + 1 byte control DAT. */
	if(length > SSD1306_LCDWIDTH) length = SSD1306_LCDWIDTH;

	datos[0] = DAT;
	for(i = 0; i < length; i++){
		datos[i + 1] = buffer[i];
	}

	HAL_I2C_Master_Transmit(&hi2c1, SSD1306_I2C_ADDRESS, datos, length + 1, OLED_I2C_TIMEOUT);
}

